<?php $sectionMetrics = ['Total de usuarios' => count($usuarios), 'Activos' => count(array_filter($usuarios,static fn($u)=>$u['estado']==='Activo')), 'Bloqueados' => count(array_filter($usuarios,static fn($u)=>$u['estado']==='Bloqueado'))]; ?>
<div class="module-metrics" aria-label="Indicadores de Usuarios registrados">
<?php foreach($sectionMetrics as $label=>$count): ?><div class="module-metric"><span><?= h($label) ?></span><strong><?= (int)$count ?></strong></div><?php endforeach; ?>
</div>
<section class="management-grid section-management" aria-label="Usuarios registrados">
<article class="dash-panel management" id="usuarios" data-module="usuarios"><div class="manage-title"><div class="manage-icon"><?= admIcon('users') ?></div><div><h2>Gestión de usuarios</h2><small>Administra los usuarios del sistema</small></div><button class="primary mini" data-new="usuarios"><?= admIcon('plus') ?> Nuevo usuario</button></div>
