<div class="table-scroll"><table><thead><tr><th>ID</th><th>Nombre</th><th>Correo</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($usuarios as $r):?><tr data-searchable="<?= h($r['id'].' '.$r['nombre'].' '.$r['correo'].' '.$r['rol'].' '.$r['estado']) ?>" data-filter-value="<?= h($r['rol']) ?>"><td><?= (int)$r['id'] ?></td><td><?= admIcon('user') ?> <?= h($r['nombre']) ?></td><td><?= h($r['correo']) ?></td><td><?= h(ucfirst($r['rol'])) ?></td><td><?= stateBadge($r['estado']) ?></td><td class="actions"><?= makeEdit('usuarios',$r) ?><?= stateButton('usuarios',$r) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="pagination"><span data-count></span><div data-pages></div></div></article>
